    pub const fn text(self) -> &'static str {
        match self {
            Rule::FileTooShort => "Reject a file shorter than HEADER_LEN + BLOCK_HEADER_LEN + INDEX_HEADER_LEN + TRAILER_LEN.",
            Rule::HeaderMagic => "Reject unless header.magic == HEADER_MAGIC.",
            Rule::HeaderVersionUnsupported => "Reject unless (header.format_major, header.format_minor) is an accepted row of the acceptance table.",
            Rule::HeaderFlagsUnknownOdd => "Reject if header.header_flags has an unknown bit set at an odd position. Unknown even bits are ignored.",
            Rule::TrailerMagic => "Reject unless the last TRAILER_LEN bytes begin with TRAILER_MAGIC.",
            Rule::TrailerSelfDigest => "Reject unless trailer.trailer_digest == BLAKE3(trailer bytes [0, 128)).",
            Rule::TrailerVersionMismatch => "Reject unless trailer.format_major == header.format_major and trailer.format_minor == header.format_minor.",
            Rule::TrailerUuidMismatch => "Reject unless trailer.archive_uuid == header.archive_uuid.",
            Rule::TrailerFlagsUnknownOdd => "Reject if trailer.trailer_flags has an unknown bit set at an odd position.",
            Rule::TrailerHeaderDigest => "Reject unless trailer.header_digest == BLAKE3(header bytes [0, HEADER_LEN)).",
            Rule::TrailerPrevOffsetNonzero => "Reject unless trailer.prev_trailer_offset == 0.",
            Rule::TrailerIndexGeometry => "Reject unless index_offset >= HEADER_LEN and index_offset + BLOCK_HEADER_LEN + index_len + TRAILER_LEN == archive_len, computed without overflow.",
            Rule::FileSizeUnclassifiable => "The file is an archive if its size == archive_len, else a sidecar if its size == HEADER_LEN + BLOCK_HEADER_LEN + index_len + TRAILER_LEN (INDX block at HEADER_LEN); reject if neither. When both hold it is an archive.",
            Rule::BlockHeaderCheck => "Reject a block whose header_check != first 8 bytes of BLAKE3(block header bytes [0, 48)).",
            Rule::IndexBlockType => "Reject unless the block at the index position has type_id INDX.",
            Rule::BlockFlagsUnknownOdd => "Reject a block whose flags have an unknown bit set at an odd position.",
            Rule::BlockSkipOnKnown => "Reject a DATA or INDX block with flags.skip set.",
            Rule::IndexLenMismatch => "Reject unless the INDX block's payload_len == trailer.index_len.",
            Rule::IndexBlockDigestMismatch => "Reject unless the INDX block's payload_digest == trailer.index_digest.",
            Rule::IndexDigest => "Reject unless BLAKE3(INDX payload) == trailer.index_digest. No payload byte is interpreted before this passes.",
            Rule::IndexTooShort => "Reject an INDX payload shorter than INDEX_HEADER_LEN.",
            Rule::IndexCodec => "Reject unless index_header.index_codec is a defined non-invalid index_codec value.",
            Rule::IndexSourceFs => "Reject unless index_header.source_fs is a defined non-invalid source_fs value.",
            Rule::IndexCapabilitiesUnknownOdd => "Reject if index_header.capabilities has an unknown bit set at an odd position.",
            Rule::RecordReservedNonzero => "Reject if any field marked reserved in any layout is nonzero.",
            Rule::TimeNsecRange => "Reject if any *_nsec field is >= NSEC_LIMIT.",
            Rule::IndexGeometry => "Reject unless INDX payload_len == INDEX_HEADER_LEN + sum(count * record size) + heap_len over the defined tables, computed without overflow.",
            Rule::IndexTombstonesNonzero => "Reject unless index_header.tombstone_count == 0, and every dir_record's tombstone_first and tombstone_count == 0.",
            Rule::HeapBounds => "Reject if any heap reference has offset + len > heap_len, computed without overflow.",
            Rule::HeapEmptyOffset => "Reject a zero-length heap reference whose offset is not 0.",
            Rule::IndexWriterEmpty => "Reject if the writer heap reference is empty.",
            Rule::InodePresentUnknownOdd => "Reject if an inode's present flags have an unknown bit set at an odd position.",
            Rule::InodeContentKind => "Reject unless every inode's content_kind is a defined non-invalid value.",
            Rule::InodeFileType => "Reject unless every inode's mode & 0xF000 is a defined non-invalid file_type.",
            Rule::DirCompleteness => "Reject unless every dir_record's completeness is complete. invalid, partial (registered, undefined) and unlisted values are all rejected.",
            Rule::ExtentRawLenRange => "Reject an extent whose raw_len is 0 or > MAX_CHUNK_RAW.",
            Rule::ExtentOffsetInBlockNonzero => "Reject an extent whose offset_in_block != 0.",
            Rule::IndexBaseRef => "Reject unless base_ref <= chain_count, and base_ref == 0 implies chain_count == 0.",
            Rule::ChainSelfOrDuplicate => "Reject a chain entry whose archive_uuid equals this archive's, or equals another entry's.",
            Rule::InodeOrder => "Reject unless every inode's ino != 0 and inodes are strictly ascending by ino.",
            Rule::InodeContentKindForType => "Reject an inode whose content_kind is not admitted for its file_type by content_kind_by_type.",
            Rule::InodeSizeForType => "Reject unless size == 0 for every type other than reg and lnk, and 1 <= size <= SYMLINK_MAX for lnk.",
            Rule::InodeFieldsForKind => "Reject unless: extent_count == 0 unless extents; chain_ref != 0 iff inherited; target_off == 0 unless symlink; rdev_major == rdev_minor == 0 unless chr or blk; content_digest all-zero unless extents or inherited.",
            Rule::InodeChainRefRange => "Reject an inherited inode whose chain_ref > chain_count.",
            Rule::InodeAbsentNonzero => "Reject if present.nsec is clear and any *_nsec is nonzero, or present.crtime is clear and crtime_sec or crtime_nsec is nonzero.",
            Rule::InodeCapabilityAbsentNonzero => "Reject if capabilities.xattrs is clear and any inode has xattr_count > 0, or capabilities.fs_flags is clear and any fs_flags != 0, or capabilities.crtime is clear and any present.crtime is set.",
            Rule::InodeExtentTiling => "Reject unless inode ranges [extent_first, extent_first + extent_count) tile the extent table in inode order: the first is 0, each begins where the previous ended, the last ends at extent_count.",
            Rule::InodeXattrTiling => "Reject unless inode ranges [xattr_first, xattr_first + xattr_count) tile the xattr table in inode order.",
            Rule::ExtentOrder => "Reject unless each inode's extents are strictly ascending and non-overlapping: file_offset[i] + raw_len[i] <= file_offset[i+1].",
            Rule::ExtentBeyondSize => "Reject an extent with file_offset + raw_len > the owning inode's size, computed without overflow.",
            Rule::XattrName => "Reject an xattr whose name is empty, contains NUL, or exceeds XATTR_NAME_MAX, or whose value exceeds XATTR_VALUE_MAX.",
            Rule::XattrOrder => "Reject unless each inode's xattrs are strictly ascending by name bytes (so unique).",
            Rule::DirBijection => "Reject unless dir_records and dir inodes correspond one to one, in the same ino order.",
            Rule::DirDirentTiling => "Reject unless dir ranges [dirent_first, dirent_first + dirent_count) tile the dirent table in dir order.",
            Rule::DirentName => "Reject a dirent name that is empty, longer than NAME_MAX, contains '/' or NUL, or is '.' or '..'.",
            Rule::DirentOrder => "Reject unless each directory's dirents are strictly ascending by name bytes (so unique).",
            Rule::DirentChildMissing => "Reject a dirent whose child_ino is not in the inode table.",
            Rule::NamespaceRoot => "Reject unless root_ino is in the inode table, is a dir, and is named by no dirent.",
            Rule::NamespaceDirLinks => "Reject unless every directory other than the root is named by exactly one dirent.",
            Rule::NamespaceOrphan => "Reject a non-directory inode named by no dirent.",
            Rule::NamespaceUnreachable => "Reject unless every directory is reachable from the root.",
            Rule::IndexInheritedInFull => "Reject an inherited inode in a full capture (base_ref == 0).",
            Rule::BlocksTiling => "Reject unless blocks, each BLOCK_HEADER_LEN + payload_len long, tile [HEADER_LEN, index_offset) exactly.",
            Rule::BlocksStrayIndex => "Reject an INDX block anywhere other than index_offset.",
            Rule::BlocksUnknownType => "Reject a block of unknown or registered-undefined type_id without flags.skip. Such a block with flags.skip is ignored.",
            Rule::ExtentBlockOffset => "Reject an extent whose block_offset is not the start of a DATA block in the tiling.",
            Rule::BlocksDataReferences => "Reject unless every DATA block is referenced by exactly one extent.",
            Rule::DataPayloadDigest => "Reject a block whose payload_digest != BLAKE3(payload).",
            Rule::DataTooShort => "Reject a DATA payload shorter than DATA_HEADER_LEN.",
            Rule::DataCodec => "Reject a DATA block whose codec is not a defined non-invalid value.",
            Rule::DataMatchesExtent => "Reject unless data_header.ino == owning inode's ino, file_offset == extent.file_offset, raw_len == extent.raw_len, raw_digest == extent.raw_digest.",
            Rule::DataStoredLen => "Reject a stored-codec DATA block whose stored byte count != raw_len.",
            Rule::DataDecode => "Reject a zstd DATA block whose stored bytes are not exactly one valid zstd frame decoding to exactly raw_len bytes.",
            Rule::DataRawDigest => "Reject a DATA block where BLAKE3(decoded raw bytes) != raw_digest.",
            Rule::InodeContentDigest => "Reject an extents inode whose content_digest != BLAKE3 of its logical content: size bytes, extent bytes at their offsets, zeros elsewhere.",
            Rule::ChainAncestorDigest => "Reject if a supplied archive with a chain entry's archive_uuid has trailer.index_digest != that entry's index_digest.",
            Rule::ChainInheritedMatch => "Reject an inherited inode unless the referenced ancestor has an inode with the same ino, generation, size and content_digest, whose content_kind is extents.",
            Rule::WriterRegisteredTypes => "A writer MUST NOT write a registered-undefined block type or enum value.",
            Rule::WriterHeapMinimal => "A writer SHOULD NOT emit heap bytes no reference addresses.",
            Rule::PolicyUnverifiedContent => "No tool emits bytes of a DATA block that failed data.payload_digest, data.decode or data.raw_digest. FUSE read returns EIO; restore does not create the file, continues with other files, and exits non-zero naming each failure.",
            Rule::PolicySidecarContent => "A content read through a sidecar fails with a distinct 'content not present' error, never a digest error.",
        }
    }

